// Concatenates supabase/migrations/*.sql (in order) into supabase/setup.sql,
// so the whole schema can be pasted into the Supabase SQL Editor in one go.
// Usage: npm run db:bundle
import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

const dir = path.join(process.cwd(), "supabase", "migrations");
const files = readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();
const parts = files.map((f) => `-- ===== ${f} =====\n${readFileSync(path.join(dir, f), "utf8").trim()}\n`);
const header =
  "-- GENERATED by `npm run db:bundle` from supabase/migrations. Do not edit by hand.\n" +
  "-- Run once on a NEW, empty Supabase project (SQL Editor → paste → Run).\n\n";
writeFileSync(path.join(process.cwd(), "supabase", "setup.sql"), header + parts.join("\n"));
console.log(`supabase/setup.sql written from ${files.length} migrations`);
